const rs = await Promise.all([
  tools.exec_command({cmd:"sed -n '1,85p' /home/axel/Archon-Horizon/src/archon_horizon/blueprint/hgraph_graph.py",workdir:"/home/axel/LeanAlgebraicGeometry-Horizon/MainProjects/Algebraic-Jacobian-Challenge-Rebuild",yield_time_ms:10000,max_output_tokens:10000}),
  tools.exec_command({cmd:"rg -n 'entry|web.tex|print.tex|content.tex' /home/axel/Archon-Horizon/src/archon_horizon/blueprint -g '*.py' | sed -n '1,180p'",workdir:"/home/axel/LeanAlgebraicGeometry-Horizon/MainProjects/Algebraic-Jacobian-Challenge-Rebuild",yield_time_ms:10000,max_output_tokens:12000}),
  tools.exec_command({cmd:"find blueprint -maxdepth 2 -type f -name '*.tex' -printf '%P\\n' | sort",workdir:"/home/axel/LeanAlgebraicGeometry-Horizon/MainProjects/Algebraic-Jacobian-Challenge-Rebuild",yield_time_ms:10000,max_output_tokens:5000})
]);
rs.forEach((r,i)=>{text(`RESULT ${i+1}`);text(r.output)});

const cmds = [
  ["lean_decls_recount", "wc -l blueprint/lean_decls; sed '/^[[:space:]]*$/d' blueprint/lean_decls | wc -l; sed '/^[[:space:]]*$/d' blueprint/lean_decls | sort -u | wc -l; sed '/^[[:space:]]*$/d' blueprint/lean_decls | sort | uniq -c | awk '$1 > 1'"],
  ["node_totals", "printf 'tex '; rg -l '^type: tex$' hgraph/nodes | wc -l; printf 'lean '; rg -l '^type: lean$' hgraph/nodes | wc -l; printf 'tex_tagged '; rg -l '^type: tex$' hgraph/nodes | xargs rg -l 'provenancetag\\{(REFERENCE|ADAPTED|CUSTOM)\\}' | wc -l; printf 'tex_multitag '; rg -l '^type: tex$' hgraph/nodes | while read f; do n=$(rg -o 'provenancetag\\{(REFERENCE|ADAPTED|CUSTOM)\\}' \"$f\" | wc -l); test \"$n\" -gt 1 && echo \"$f\"; done | wc -l"],
  ["global_stale", "rg -l '^stale: true$' hgraph/nodes | wc -l; printf 'stale_tex '; rg -l '^stale: true$' hgraph/nodes | xargs rg -l '^type: tex$' | wc -l; printf 'stale_lean '; rg -l '^stale: true$' hgraph/nodes | xargs rg -l '^type: lean$' | wc -l"],
  ["root_tags_now", "rg -n '\\b(REFERENCE|ADAPTED|CUSTOM|TO CHECK)\\b' AlgebraicJacobian/Challenge.lean; rg -n '\\b(REFERENCE|ADAPTED|CUSTOM|TO CHECK)\\b' AlgebraicJacobian/Picard/Pic0EndgameContract.lean || true"]
];
const results = await Promise.all(cmds.map(([name, cmd]) =>
  tools.exec_command({
    cmd,
    workdir: "/home/axel/LeanAlgebraicGeometry-Horizon/MainProjects/Algebraic-Jacobian-Challenge-Rebuild",
    yield_time_ms: 30000,
    max_output_tokens: 20000
  })
));
for (let i=0;i<results.length;i++) text(`${cmds[i][0]}\n${results[i].output}`);

const rs = await Promise.all([
  tools.exec_command({cmd:"find hgraph/nodes -type f -name '*.md' -maxdepth 1 -print0 | xargs -0 rg -h '^file:' | sed 's/^file: //' | awk '!/^AlgebraicJacobian\\//' | sort -u | sed -n '1,160p'",workdir:"/home/axel/LeanAlgebraicGeometry-Horizon/MainProjects/Algebraic-Jacobian-Challenge-Rebuild",yield_time_ms:10000,max_output_tokens:10000}),
  tools.exec_command({cmd:"find AlgebraicJacobian -type f -name '*.lean' | wc -l && find . -type f -name '*.lean' -not -path './.lake/*' -not -path './lake-packages/*' | wc -l",workdir:"/home/axel/LeanAlgebraicGeometry-Horizon/MainProjects/Algebraic-Jacobian-Challenge-Rebuild",yield_time_ms:10000,max_output_tokens:5000}),
  tools.exec_command({cmd:"rg -n '^file:' hgraph/nodes/*.md | sed -E 's/.*file: //' | sort -u | wc -l",workdir:"/home/axel/LeanAlgebraicGeometry-Horizon/MainProjects/Algebraic-Jacobian-Challenge-Rebuild",yield_time_ms:10000,max_output_tokens:3000}),
  tools.exec_command({cmd:"rg -n '^file:' hgraph/nodes/*.md | sed -E 's/.*file: //' | sort -u | tail -n 40",workdir:"/home/axel/LeanAlgebraicGeometry-Horizon/MainProjects/Algebraic-Jacobian-Challenge-Rebuild",yield_time_ms:10000,max_output_tokens:8000})
]);
rs.forEach((r,i)=>{text(`RESULT ${i+1}`);text(r.output)});

const cmds = [
  ["pwd + status", "pwd; git status --short", "."],
  ["tag counts", "rg -n '\\\\provenancetag\\{|TO CHECK|tocheck|to-check' blueprint/src/chapters | wc -l; rg -o '\\\\provenancetag\\{(REFERENCE|ADAPTED|CUSTOM)\\}' blueprint/src/chapters | sort | uniq -c", "."],
  ["chapter files", "rg --files blueprint/src/chapters | sort", "."],
  ["live diff stat", "git diff --stat -- blueprint/src/chapters blueprint/src/*.tex AlgebraicJacobian/Challenge.lean", "."]
];
const out = await Promise.all(cmds.map(async ([label, cmd, workdir]) => {
  const r = await tools.exec_command({cmd, workdir, yield_time_ms:10000, max_output_tokens:3000});
  return `## ${label}\n${r.output}`;
}));
text(out.join("\n"));

const r = await tools.exec_command({
  cmd: "rg -n '\\\\newcommand\\{\\\\source|source\\{|provenancetag|begin\\{(definition|lemma|theorem|proposition|corollary|remark)' blueprint/src | head -80",
  workdir: ".",
  yield_time_ms: 10000,
  max_output_tokens: 12000
});
text(r.output);

const qs = [
  ["adaptation prose", "rg -n -i 'adapt|strengthen|weaker|stronger|not assumed|without (the )?(Noetherian|genus)|in contrast|differs|variation|generaliz|specializ|reformulat|instead of|does not directly|not quite|slightly' blueprint/src/chapters"],
  ["source caveats", "rg -n -i 'reference|source|Milne|Kleiman|Hartshorne|Mumford|Nitsure|Papaioannou|Stacks' blueprint/src/chapters | rg -i 'only|but|however|assum|scope|page|argument|proof|uses|does not|not'"],
  ["unproved/check language", "rg -n -i 'unproved|gap|pending|TODO|FIXME|open obligation|not yet|missing|unsound|mismatch|scope' blueprint/src/chapters"]
];
const out = await Promise.all(qs.map(async ([label, cmd]) => {
  const r = await tools.exec_command({cmd, workdir:".", yield_time_ms:10000, max_output_tokens:20000});
  return `## ${label}\n${r.output}`;
}));
text(out.join("\n"));

