## RR inequality
   170	  \leanok
   171	  \source{papaioannou-algebraic-rr:page-0006}
   172	  For an integral scheme \(X\) with generic point \(\eta\), a \emph{Weil divisor} is a finitely
   173	  supported \(\Z\)-valued function on the non-generic points, i.e.\ an element of the free abelian
   174	  group
   175	  \[
   176	    \Div(X) \;=\; \bigl(\{ x \in X : x \neq \eta \} \to_{\mathrm{fin}} \Z\bigr)
   177	  \]
   178	  on the set of non-generic points. It carries the pointwise abelian-group structure and the
   179	  pointwise partial order, both independent of any base field. For the curve \(X\) the
   180	  non-generic points are exactly the closed points (\ref{thm:closedpoint_isClosed}), so a Weil
   181	  divisor is a finite formal \(\Z\)-combination of closed points.
   182	\end{definition}
   183	
   184	\begin{definition}[The degree of a Weil divisor]
   185	  \label{def:curveDivisor_deg}
   186	  \lean{AlgebraicGeometry.Scheme.CurveDivisor.deg}
   187	  \uses{def:curveDivisor, def:residueDeg}
   188	  \leanok
   189	  \source{papaioannou-algebraic-rr:page-0007}
   190	  For a scheme \(X\) over \(\Spec K\) and a Weil divisor \(D \in \Div(X)\), the \emph{degree} of
   191	  \(D\), weighted by the residue degrees over the base field, is
   192	  \[
   193	    \deg_K D \;=\; \sum_{x} D_x \cdot [\kappa(x) : K] \;\in\; \Z ,
   194	  \]
   195	  the finite sum over the support of \(D\) of the coefficients \(D_x\) times the residue degrees
   196	  \([\kappa(x) : K]\) of \ref{def:residueDeg}.
   197	\end{definition}
   198	
   199	\begin{theorem}[The degree is a group homomorphism]
   200	  \label{thm:curveDivisor_deg_hom}
   201	  \lean{AlgebraicGeometry.Scheme.CurveDivisor.deg_zero,
   202	    AlgebraicGeometry.Scheme.CurveDivisor.deg_add,
   203	    AlgebraicGeometry.Scheme.CurveDivisor.deg_neg}
   204	  \uses{def:curveDivisor_deg}
   205	  \leanok
   206	  \source{papaioannou-algebraic-rr:page-0007}
   207	  The degree map \(\deg_K : \Div(X) \to \Z\) is a homomorphism of abelian groups: it satisfies
   208	  \(\deg_K 0 = 0\), \(\deg_K(D + D') = \deg_K D + \deg_K D'\) and \(\deg_K(-D) = -\deg_K D\).
   209	\end{theorem}
   210	\begin{proof}
   211	  \leanok
   212	  The degree is the finitely supported sum \(D \mapsto \sum_x D_x \cdot [\kappa(x) : K]\). The
   213	  zero divisor has empty support, so \(\deg_K 0 = 0\). For additivity, the summand
   214	  \(n \mapsto n \cdot [\kappa(x) : K]\) is, at each point \(x\), additive in the coefficient
   215	  \(n\) and vanishes at \(n = 0\); hence the finitely supported sum of the pointwise sums
   216	  \((D + D')_x = D_x + D'_x\) splits as \(\sum_x D_x[\kappa(x):K] + \sum_x D'_x[\kappa(x):K]\),
   217	  giving \(\deg_K(D + D') = \deg_K D + \deg_K D'\). Finally, applying additivity to \(D\) and
   218	  \(-D\) and using \(\deg_K 0 = 0\) yields \(\deg_K(-D) = -\deg_K D\).
   219	\end{proof}
